% 异常值检测（使用四分位数法）
fprintf('\n=== 异常值检测 ===\n');
variables = {'gestational_weeks', 'BMI_data', 'Y_chromosome_concentration'};
var_names = {'孕周数', 'BMI', 'Y染色体浓度'};

for i = 1:length(variables)
    data = eval(variables{i});
    Q1 = prctile(data, 25);
    Q3 = prctile(data, 75);
    IQR = Q3 - Q1;
    lower_bound = Q1 - 1.5 * IQR;
    upper_bound = Q3 + 1.5 * IQR;
    outliers = sum(data < lower_bound | data > upper_bound);
    fprintf('%s异常值数量: %d (%.1f%%)\n', var_names{i}, outliers, outliers/n*100);
end



%% 相关性分析
