    fprintf('%12s', var_labels{j});
end
fprintf('\n');

for i = 1:length(var_labels)
    fprintf('%-12s', var_labels{i});
    for j = 1:length(var_labels)
        fprintf('%12.4f', corr_matrix(i,j));
    end
    fprintf('\n');
end

