%% 模型构建和比较
fprintf('\n=== 模型构建和比较 ===\n');

% 准备数据
X = [gestational_weeks, BMI_data];  % 自变量矩阵
Y = Y_chromosome_concentration;      % 因变量
X_with_intercept = [ones(n,1), X];   % 添加截距项



%% 模型1: 多元线性回归模型
fprintf('\n--- 模型1: 多元线性回归模型 ---\n');
mdl1 = fitlm(X, Y);
fprintf('模型方程: Y = %.6f + %.6f*GestationalWeeks + %.6f*BMI\n', ...
        mdl1.Coefficients.Estimate(1), mdl1.Coefficients.Estimate(2), mdl1.Coefficients.Estimate(3));
fprintf('R² = %.4f, 调整R² = %.4f\n', mdl1.Rsquared.Ordinary, mdl1.Rsquared.Adjusted);
fprintf('F统计量 = %.2f, p值 = %.6f\n', mdl1.anova.F(1), mdl1.anova.pValue(1));
fprintf('AIC = %.2f, BIC = %.2f\n', mdl1.ModelCriterion.AIC, mdl1.ModelCriterion.BIC);

% 系数显著性检验
fprintf('\n系数显著性检验:\n');
coef_names = {'截距', '孕周数', 'BMI'};
for i = 1:3
    fprintf('%s: 系数=%.6f, t=%.3f, p=%.6f\n', coef_names{i}, ...
            mdl1.Coefficients.Estimate(i), mdl1.Coefficients.tStat(i), mdl1.Coefficients.pValue(i));
end



%% 模型2: 仅孕周数的简单线性回归
fprintf('\n--- 模型2: 简单线性回归 (仅孕周数) ---\n');
mdl2 = fitlm(gestational_weeks, Y);
fprintf('模型方程: Y = %.6f + %.6f*GestationalWeeks\n', ...
        mdl2.Coefficients.Estimate(1), mdl2.Coefficients.Estimate(2));
fprintf('R² = %.4f, 调整R² = %.4f\n', mdl2.Rsquared.Ordinary, mdl2.Rsquared.Adjusted);
fprintf('AIC = %.2f, BIC = %.2f\n', mdl2.ModelCriterion.AIC, mdl2.ModelCriterion.BIC);



%% 模型3: 多项式回归 (孕周数二次项)
fprintf('\n--- 模型3: 多项式回归模型 ---\n');
X_poly = [gestational_weeks, BMI_data, gestational_weeks.^2];
mdl3 = fitlm(X_poly, Y);
fprintf('R² = %.4f, 调整R² = %.4f\n', mdl3.Rsquared.Ordinary, mdl3.Rsquared.Adjusted);
fprintf('AIC = %.2f, BIC = %.2f\n', mdl3.ModelCriterion.AIC, mdl3.ModelCriterion.BIC);



%% 模型4: 对数变换模型
fprintf('\n--- 模型4: 对数变换模型 ---\n');
log_Y = log(Y);
mdl4 = fitlm(X, log_Y);
fprintf('R² = %.4f, 调整R² = %.4f\n', mdl4.Rsquared.Ordinary, mdl4.Rsquared.Adjusted);
fprintf('AIC = %.2f, BIC = %.2f\n', mdl4.ModelCriterion.AIC, mdl4.ModelCriterion.BIC);



%% 模型5: 交互效应模型
fprintf('\n--- 模型5: 交互效应模型 ---\n');
X_interact = [gestational_weeks, BMI_data, gestational_weeks.*BMI_data];
mdl5 = fitlm(X_interact, Y);
fprintf('R² = %.4f, 调整R² = %.4f\n', mdl5.Rsquared.Ordinary, mdl5.Rsquared.Adjusted);
fprintf('AIC = %.2f, BIC = %.2f\n', mdl5.ModelCriterion.AIC, mdl5.ModelCriterion.BIC);



%% 模型比较总结
fprintf('\n=== 模型比较总结 ===\n');
models = {'多元线性回归', '简单线性回归', '多项式回归', '对数变换', '交互效应'};
R2_values = [mdl1.Rsquared.Ordinary, mdl2.Rsquared.Ordinary, mdl3.Rsquared.Ordinary, ...
             mdl4.Rsquared.Ordinary, mdl5.Rsquared.Ordinary];
AIC_values = [mdl1.ModelCriterion.AIC, mdl2.ModelCriterion.AIC, mdl3.ModelCriterion.AIC, ...
              mdl4.ModelCriterion.AIC, mdl5.ModelCriterion.AIC];
BIC_values = [mdl1.ModelCriterion.BIC, mdl2.ModelCriterion.BIC, mdl3.ModelCriterion.BIC, ...
              mdl4.ModelCriterion.BIC, mdl5.ModelCriterion.BIC];

fprintf('%-20s %8s %8s %8s\n', '模型', 'R²', 'AIC', 'BIC');
fprintf('%-20s %8s %8s %8s\n', '----', '--', '---', '---');
for i = 1:length(models)
    fprintf('%-20s %8.4f %8.2f %8.2f\n', models{i}, R2_values(i), AIC_values(i), BIC_values(i));
end



%% 7. 分段非线性回归模型分析
fprintf('\n=== 分段非线性回归模型分析 ===\n');

% 创建分段变量和高次项
breakpoint = 20; % 分段点设为20周
segment_indicator = gestational_weeks > breakpoint;
segment_weeks = segment_indicator .* (gestational_weeks - breakpoint);

% 创建高次项
gestational_weeks_sq = gestational_weeks.^2;
BMI_sq = BMI_data.^2;
segment_weeks_sq = segment_weeks.^2;

% 创建交互项
interaction_weeks_BMI = gestational_weeks .* BMI_data;
interaction_segment_BMI = segment_weeks .* BMI_data;

%% 7.1 基础分段线性模型
fprintf('\n--- 7.1 基础分段线性回归模型 ---\n');
X_segment_linear = [ones(n,1), gestational_weeks, BMI_data, segment_weeks];
beta_segment_linear = X_segment_linear \ Y_chromosome_concentration;

% 计算拟合值和残差
y_pred_segment_linear = X_segment_linear * beta_segment_linear;
residuals_segment_linear = Y_chromosome_concentration - y_pred_segment_linear;
SSE_segment_linear = sum(residuals_segment_linear.^2);
SST = sum((Y_chromosome_concentration - mean(Y_chromosome_concentration)).^2);
R2_segment_linear = 1 - SSE_segment_linear/SST;
R2_adj_segment_linear = 1 - (SSE_segment_linear/(n-4))/(SST/(n-1));

% F检验
MSE_segment_linear = SSE_segment_linear/(n-4);
MSR_segment_linear = (SST - SSE_segment_linear)/3;
F_segment_linear = MSR_segment_linear/MSE_segment_linear;
p_F_segment_linear = 1 - fcdf(F_segment_linear, 3, n-4);

fprintf('分段线性模型结果:\n');
fprintf('R² = %.4f, 调整R² = %.4f\n', R2_segment_linear, R2_adj_segment_linear);
fprintf('F统计量 = %.2f, p值 = %.6f\n', F_segment_linear, p_F_segment_linear);

% 系数显著性检验
se_segment_linear = sqrt(diag(MSE_segment_linear * inv(X_segment_linear'*X_segment_linear)));
t_segment_linear = beta_segment_linear ./ se_segment_linear;
p_t_segment_linear = 2 * (1 - tcdf(abs(t_segment_linear), n-4));

fprintf('\n系数估计和显著性检验:\n');
coef_names_segment = {'截距', '孕周数', 'BMI', '分段项(>20周)'};
for i = 1:4
    fprintf('%s: β=%.6f, SE=%.6f, t=%.3f, p=%.6f', ...
        coef_names_segment{i}, beta_segment_linear(i), se_segment_linear(i), ...
        t_segment_linear(i), p_t_segment_linear(i));
    if p_t_segment_linear(i) < 0.001
        fprintf(' ***\n');
    elseif p_t_segment_linear(i) < 0.01
        fprintf(' **\n');
    elseif p_t_segment_linear(i) < 0.05
        fprintf(' *\n');
    else
        fprintf('\n');
    end
end

%% 7.2 分段非线性模型（含高次项）
fprintf('\n--- 7.2 分段非线性回归模型（含高次项） ---\n');
X_segment_poly = [ones(n,1), gestational_weeks, BMI_data, segment_weeks, ...
                  gestational_weeks_sq, BMI_sq, segment_weeks_sq];
beta_segment_poly = X_segment_poly \ Y_chromosome_concentration;

