fprintf('\n系数估计和显著性检验:\n');
coef_names_poly = {'截距', '孕周数', 'BMI', '分段项', '孕周数²', 'BMI²', '分段项²'};
for i = 1:7
    fprintf('%s: β=%.6f, SE=%.6f, t=%.3f, p=%.6f', ...
        coef_names_poly{i}, beta_segment_poly(i), se_segment_poly(i), ...
