%% 7.3 分段非线性模型（含交互项）
fprintf('\n--- 7.3 分段非线性回归模型（含交互项） ---\n');
X_segment_interaction = [ones(n,1), gestational_weeks, BMI_data, segment_weeks, ...
                        gestational_weeks_sq, BMI_sq, segment_weeks_sq, ...
                        interaction_weeks_BMI, interaction_segment_BMI];
