%% 7.4 模型比较和AIC/BIC计算
fprintf('\n--- 7.4 分段模型比较 ---\n');

% 计算AIC和BIC
AIC_segment_linear = n*log(SSE_segment_linear/n) + 2*4;
BIC_segment_linear = n*log(SSE_segment_linear/n) + log(n)*4;

AIC_segment_poly = n*log(SSE_segment_poly/n) + 2*7;
BIC_segment_poly = n*log(SSE_segment_poly/n) + log(n)*7;

AIC_segment_interaction = n*log(SSE_segment_interaction/n) + 2*9;
BIC_segment_interaction = n*log(SSE_segment_interaction/n) + log(n)*9;

fprintf('模型比较:\n');
fprintf('模型                    R²      调整R²    AIC      BIC      F统计量   p值\n');
fprintf('分段线性              %.4f   %.4f   %.2f   %.2f   %.2f    %.6f\n', ...
    R2_segment_linear, R2_adj_segment_linear, AIC_segment_linear, BIC_segment_linear, ...
    F_segment_linear, p_F_segment_linear);
fprintf('分段非线性(高次项)     %.4f   %.4f   %.2f   %.2f   %.2f    %.6f\n', ...
    R2_segment_poly, R2_adj_segment_poly, AIC_segment_poly, BIC_segment_poly, ...
    F_segment_poly, p_F_segment_poly);
fprintf('分段非线性(交互项)     %.4f   %.4f   %.2f   %.2f   %.2f    %.6f\n', ...
    R2_segment_interaction, R2_adj_segment_interaction, AIC_segment_interaction, BIC_segment_interaction, ...
    F_segment_interaction, p_F_segment_interaction);

% 确定最佳模型 (修改为分段非线性交互项模型)
% 构建最佳模型的设计矩阵
X_best = [ones(n,1), gestational_weeks, BMI_data, segment_weeks, ...
          gestational_weeks_sq, BMI_sq, segment_weeks_sq, ...
          interaction_weeks_BMI, interaction_segment_BMI];

% 使用最佳模型参数
best_beta = beta_segment_interaction;
best_fitted = y_pred_segment_interaction;
best_residuals = residuals_segment_interaction;
best_R2 = R2_segment_interaction;
best_R2_adj = R2_adj_segment_interaction;
best_F = F_segment_interaction;
best_p_F = p_F_segment_interaction;
best_MSE = MSE_segment_interaction;

fprintf('\n推荐模型: 分段非线性回归模型（含交互项）\n');
fprintf('理由: 1) 最高的调整R² 2) 考虑了非线性和交互效应 3) 捕捉了数据的复杂关系 4) 生物学意义明确\n');

% ---------------------------------------------------------------- %

%% 模型诊断 (基于分段非线性交互项模型)
fprintf('\n=== 模型诊断 ===\n');

% 获取残差和拟合值
residuals = best_residuals;
fitted_values = best_fitted;
standardized_residuals = residuals / sqrt(best_MSE);

% ---------------------------------------------------------------- %

%% 1. 残差正态性检验
fprintf('\n--- 1. 残差正态性检验 ---\n');

% 使用Jarque-Bera检验
[h_jb, p_jb] = jbtest(residuals);
fprintf('Jarque-Bera检验: h=%d, p=%.6f\n', h_jb, p_jb);
if p_jb > 0.05
    fprintf('结论: 残差服从正态分布 (p > 0.05)\n');
else
    fprintf('结论: 残差不服从正态分布 (p ≤ 0.05)\n');
end

% 补充Kolmogorov-Smirnov检验
[h_ks, p_ks] = kstest(standardized_residuals);
fprintf('Kolmogorov-Smirnov检验: h=%d, p=%.6f\n', h_ks, p_ks);
if p_ks > 0.05
    fprintf('结论: 残差服从正态分布 (p > 0.05)\n');
else
    fprintf('结论: 残差不服从正态分布 (p ≤ 0.05)\n');
end

% ---------------------------------------------------------------- %

%% 2. 方差齐性检验 (Breusch-Pagan检验)
fprintf('\n--- 2. 方差齐性检验 ---\n');

% 计算Breusch-Pagan统计量
residuals_squared = residuals.^2;
% 对主要预测变量进行方差齐性检验
X_bp = [gestational_weeks, BMI_data];
mdl_bp = fitlm(X_bp, residuals_squared);
LM_bp = n * mdl_bp.Rsquared.Ordinary;
p_bp = 1 - chi2cdf(LM_bp, 2);

fprintf('Breusch-Pagan检验: LM=%.4f, p=%.6f\n', LM_bp, p_bp);
if p_bp > 0.05
    fprintf('结论: 方差齐性假设成立 (p > 0.05)\n');
else
    fprintf('结论: 存在异方差性 (p ≤ 0.05)\n');
end

% ---------------------------------------------------------------- %

%% 3. 多重共线性检验
fprintf('\n--- 3. 多重共线性检验 ---\n');

% 计算主要变量的VIF (方差膨胀因子)
X_main = [gestational_weeks, BMI_data];
X_centered = X_main - mean(X_main);
R_matrix = corrcoef(X_centered);
VIF = diag(inv(R_matrix));

fprintf('主要变量的方差膨胀因子 (VIF):\n');
fprintf('孕周数: VIF = %.4f\n', VIF(1));
fprintf('BMI: VIF = %.4f\n', VIF(2));

% 检查高次项和交互项的共线性
X_all_centered = X_best(:,2:end) - mean(X_best(:,2:end));
R_all = corrcoef(X_all_centered);
max_corr = max(max(abs(R_all - eye(size(R_all)))));
fprintf('变量间最大相关系数: %.4f\n', max_corr);

if max(VIF) < 5
    fprintf('结论: 主要变量无严重多重共线性问题 (VIF < 5)\n');
elseif max(VIF) < 10
    fprintf('结论: 主要变量存在中等多重共线性 (5 ≤ VIF < 10)\n');
else
    fprintf('结论: 主要变量存在严重多重共线性问题 (VIF ≥ 10)\n');
end

if max_corr < 0.8
    fprintf('结论: 所有变量间相关性可接受 (max|r| < 0.8)\n');
else
    fprintf('警告: 存在高度相关的变量 (max|r| ≥ 0.8)\n');
end

% ---------------------------------------------------------------- %

%% 4. 影响点分析
fprintf('\n--- 4. 影响点分析 ---\n');

% 计算杠杆值和Cook距离
p_params = size(X_best, 2);  % 参数个数
leverage = diag(X_best * inv(X_best' * X_best) * X_best');
cook_distance = (residuals.^2 ./ (p_params * best_MSE)) .* (leverage ./ (1-leverage).^2);

% 识别异常影响点
high_leverage = leverage > 2*p_params/n;  % 高杠杆点
high_cook = cook_distance > 4/n;         % 高Cook距离点

fprintf('高杠杆点数量: %d (阈值: %.4f)\n', sum(high_leverage), 2*p_params/n);
fprintf('高Cook距离点数量: %d (阈值: %.4f)\n', sum(high_cook), 4/n);

if sum(high_cook) == 0
    fprintf('结论: 无显著影响点\n');
else
    fprintf('结论: 存在 %d 个潜在影响点\n', sum(high_cook));
    influential_points = find(high_cook);
    fprintf('影响点索引: ');
    fprintf('%d ', influential_points(1:min(10, length(influential_points))));
    if length(influential_points) > 10
        fprintf('...(共%d个)', length(influential_points));
    end
    fprintf('\n');
end

% ---------------------------------------------------------------- %

%% 5. 独立性检验 (Durbin-Watson检验)
fprintf('\n--- 5. 独立性检验 ---\n');

% 计算Durbin-Watson统计量
dw_stat = sum(diff(residuals).^2) / sum(residuals.^2);
fprintf('Durbin-Watson统计量: %.4f\n', dw_stat);

if dw_stat > 1.5 && dw_stat < 2.5
    fprintf('结论: 残差独立性假设成立 (1.5 < DW < 2.5)\n');
else
    fprintf('结论: 可能存在自相关问题\n');
end

