% ---------------------------------------------------------------- %

%% 模型预测和实际应用
fprintf('\n=== 模型预测和实际应用 ===\n');

%% 预测函数定义
predict_y_concentration = @(weeks, bmi) ...
    best_beta(1) + ...                                          % 截距
    best_beta(2) * weeks + ...                                  % 孕周数
    best_beta(3) * bmi + ...                                    % BMI
    best_beta(4) * max(0, weeks - breakpoint) + ...            % 分段项
    best_beta(5) * weeks.^2 + ...                              % 孕周数²
    best_beta(6) * bmi.^2 + ...                                 % BMI²
    best_beta(7) * max(0, weeks - breakpoint).^2 + ...         % 分段项²
    best_beta(8) * weeks .* bmi + ...                          % 孕周×BMI交互项
    best_beta(9) * max(0, weeks - breakpoint) .* bmi;          % 分段×BMI交互项

%% 预测示例
fprintf('\n--- 预测示例 ---\n');

% 示例数据点
example_weeks = [12, 16, 20, 24];
example_bmi = [28, 30, 32, 35];

fprintf('预测示例 (分段非线性交互项模型):\n');
fprintf('%-8s %-8s %-12s %-12s\n', '孕周', 'BMI', '预测值', '标准误差');
fprintf('%-8s %-8s %-12s %-12s\n', '----', '---', '------', '--------');

for i = 1:length(example_weeks)
    for j = 1:length(example_bmi)
        pred_val = predict_y_concentration(example_weeks(i), example_bmi(j));
        
        % 计算预测标准误差
        x_new = [1, example_weeks(i), example_bmi(j), max(0, example_weeks(i) - breakpoint), ...
                 example_weeks(i)^2, example_bmi(j)^2, max(0, example_weeks(i) - breakpoint)^2, ...
                 example_weeks(i) * example_bmi(j), max(0, example_weeks(i) - breakpoint) * example_bmi(j)];
        pred_se = sqrt(best_MSE * (1 + x_new * inv(X_best' * X_best) * x_new'));
        
        fprintf('%-8.1f %-8.1f %-12.6f %-12.6f\n', ...
                example_weeks(i), example_bmi(j), pred_val, pred_se);
    end
end

