% 下面这一段就是偏依赖图的部分

%% 敏感性分析
fprintf('\n--- 敏感性分析 ---\n');

% 固定BMI=32，分析孕周数变化的影响
fixed_bmi = 32;
week_range = 11:1:29;
predictions_weeks = arrayfun(@(w) predict_y_concentration(w, fixed_bmi), week_range);

fprintf('固定BMI=%.1f时，孕周数对Y染色体浓度的影响:\n', fixed_bmi);

% 计算边际效应
marginal_effect_weeks = zeros(size(week_range));
for i = 1:length(week_range)
    w = week_range(i);
    marginal_effect_weeks(i) = best_beta(2) + ...              % 线性项
                              2 * best_beta(5) * w + ...       % 二次项
                              best_beta(8) * fixed_bmi;        % 交互项
    if w > breakpoint
        marginal_effect_weeks(i) = marginal_effect_weeks(i) + ...
                                  best_beta(4) + ...           % 分段线性项
                                  2 * best_beta(7) * (w - breakpoint) + ... % 分段二次项
                                  best_beta(9) * fixed_bmi;    % 分段交互项
    end
end

fprintf('孕周数的边际效应范围: [%.6f, %.6f]\n', min(marginal_effect_weeks), max(marginal_effect_weeks));

% 固定孕周=16，分析BMI变化的影响
fixed_weeks = 16;
bmi_range = 26:1:47;
predictions_bmi = arrayfun(@(b) predict_y_concentration(fixed_weeks, b), bmi_range);

fprintf('固定孕周=%.1f时，BMI对Y染色体浓度的影响:\n', fixed_weeks);

% 计算BMI的边际效应
segment_val = max(0, fixed_weeks - breakpoint);
marginal_effect_bmi = best_beta(3) + ...                       % 线性项
                     2 * best_beta(6) * mean(bmi_range) + ...  % 二次项
                     best_beta(8) * fixed_weeks + ...          % 交互项
                     best_beta(9) * segment_val;               % 分段交互项

fprintf('BMI的边际效应 (在BMI均值处): %.6f\n', marginal_effect_bmi);

%% 预测可视化
figure('Position', [100, 100, 1200, 500]);

subplot(1,2,1);
plot(week_range, predictions_weeks, 'b-', 'LineWidth', 2);
hold on;
xline(breakpoint, 'r--', 'LineWidth', 2, 'DisplayName', '分段点');
xlabel('孕周数 (周)');
ylabel('预测Y染色体浓度');
title(sprintf('Y染色体浓度随孕周数变化 (BMI=%.1f)', fixed_bmi));
legend('Location', 'best');
grid on;

subplot(1,2,2);
plot(bmi_range, predictions_bmi, 'r-', 'LineWidth', 2);
xlabel('BMI (kg/m²)');
ylabel('预测Y染色体浓度');
title(sprintf('Y染色体浓度随BMI变化 (孕周=%.1f)', fixed_weeks));
grid on;

sgtitle('分段非线性交互项模型预测可视化', 'FontSize', 14, 'FontWeight', 'bold');

% ---------------------------------------------------------------- %

%% 交叉验证
fprintf('\n=== 模型交叉验证 ===\n');

% K折交叉验证 (K=10)
k = 10;
cv_indices = crossvalind('Kfold', n, k);
mse_cv = zeros(k, 1);
r2_cv = zeros(k, 1);

fprintf('10折交叉验证结果 (分段非线性交互项模型):\n');
fprintf('折数  MSE      R²\n');
fprintf('---  ------   ------\n');

for i = 1:k
    % 训练集和测试集
    test_idx = (cv_indices == i);
    train_idx = ~test_idx;
    
    X_train = X_best(train_idx, :);
    Y_train = Y_chromosome_concentration(train_idx);
    X_test = X_best(test_idx, :);
    Y_test = Y_chromosome_concentration(test_idx);
    
    % 训练模型
    beta_cv = X_train \ Y_train;
    
    % 预测
    Y_pred = X_test * beta_cv;
    
    % 计算指标
    mse_cv(i) = mean((Y_test - Y_pred).^2);
    ss_tot = sum((Y_test - mean(Y_test)).^2);
    ss_res = sum((Y_test - Y_pred).^2);
    r2_cv(i) = 1 - ss_res/ss_tot;
    
    fprintf('%-3d  %.4f   %.4f\n', i, mse_cv(i), r2_cv(i));
end

fprintf('\n交叉验证总结:\n');
fprintf('平均MSE: %.6f ± %.6f\n', mean(mse_cv), std(mse_cv));
fprintf('平均R²: %.4f ± %.4f\n', mean(r2_cv), std(r2_cv));

% 与原模型比较
fprintf('\n与原模型比较:\n');
fprintf('原模型R²: %.4f\n', best_R2);
fprintf('交叉验证R²: %.4f\n', mean(r2_cv));
fprintf('差异: %.4f\n', best_R2 - mean(r2_cv));

if abs(best_R2 - mean(r2_cv)) < 0.05
    fprintf('结论: 模型具有良好的泛化能力\n');
else
    fprintf('结论: 模型可能存在过拟合风险\n');
end

